Schema:
CREATE TABLE rentals (id INTEGER, item_name TEXT, returned_at TEXT);
Question: List unreturned rental items ordered by rental ID.

Schema:
CREATE TABLE expenses (id INTEGER, category TEXT, amount REAL, approved INTEGER);
Question: Sum approved expenses in each category, largest total first, then category.

Schema:
CREATE TABLE players (id INTEGER, name TEXT, score INTEGER);
Question: Return the five highest scoring players, breaking ties by ID ascending.

Schema:
CREATE TABLE folders (id INTEGER, name TEXT); CREATE TABLE documents (id INTEGER, folder_id INTEGER);
Question: Find folders with no documents. Sort by folder ID.

Schema:
CREATE TABLE shifts (id INTEGER, employee_id INTEGER, hours REAL);
Question: Show employees whose recorded hours sum to more than 40, ordered by employee ID.

Schema:
CREATE TABLE mail_queue (id INTEGER, sent_at TEXT, attempts INTEGER);
Question: Count unsent messages with fewer than 3 delivery attempts.

Schema:
CREATE TABLE devices (id INTEGER, name TEXT, firmware TEXT);
Question: List devices whose firmware is missing, ordered by name.

Schema:
CREATE TABLE allocations (project_id INTEGER, person_id INTEGER);
Question: Count distinct people allocated to each project, ordered by project ID.

Schema:
CREATE TABLE appointments (id INTEGER, starts_at TEXT, cancelled INTEGER);
Question: List non-cancelled appointment IDs starting on 2026-08-15, with 16 August as the exclusive end. Sort by start time and ID.

Schema:
CREATE TABLE surveys (id INTEGER, response TEXT);
Question: Count non-null responses, including empty strings.
